{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or neutral, especially after recent spikes.",
    "Reduce forecast overshoots following strong upward sentiment moves by applying a 10-15% dampening factor.",
    "Apply mean reversion bias: if forecast is > 10% above recent 7-day average, reduce by 5-8%.",
    "Increase forecast sensitivity to sentiment shifts: if sentiment turns positive after a downtrend, raise forecast by 3-5%.",
    "Correct for lag: if true outcome is > 2% above forecast 3 days later, adjust next forecast downward by 1-2%.",
    "Avoid overconfidence in high sentiment periods: if sentiment > 0.5 and forecast > 70, cap at 70.5 to prevent overestimation."
  ]
}
